package com.enterprise.events;

import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

public record OrderCreatedEvent(Long orderId, String customerEmail) {}

@Component
public class OrderPublisher {
    private final ApplicationEventPublisher publisher;

    public OrderPublisher(ApplicationEventPublisher publisher) {
        this.publisher = publisher;
    }

    public void processOrder(Long orderId, String email) {
        // Business logic execution...
        publisher.publishEvent(new OrderCreatedEvent(orderId, email));
    }
}

@Component
public class OrderEventListener {

    @Async("taskExecutor")
    @EventListener
    public void handleOrderAsync(OrderCreatedEvent event) {
        // Executes on a separate thread pool thread; safe for slow I/O like email dispatching
        System.out.println("Sending async confirmation email for order: " + event.orderId());
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void handleOrderCommitted(OrderCreatedEvent event) {
        // Executes only after the surrounding database transaction successfully commits
        System.out.println("Order committed to DB, updating audit logs for: " + event.orderId());
    }
}
